pub const VERIFY_REPAIR_ATTEMPTS: u32 = 3;
/// Bounded strictly-additive deepening passes run before verification.
/// Deepening passes that add worked examples and traces while the guide is under the
/// depth target. Each pass is strictly additive and structurally validated.
pub const GUIDE_DEPTH_PASSES: u32 = 2;
/// Pedagogy passes that run after the depth passes. Each one asks the verifier for its
/// advisory (missing examples, terms used before definition, unwoven figures, thin
/// sections) and fixes exactly those items.
pub const GUIDE_PEDAGOGY_PASSES: u32 = 1;
/// How many times the writer harness may run `./verify_draft.sh` and fix what it reports
/// within one session before it must stop and report what remains.
pub const HARNESS_VERIFY_ROUNDS: u32 = 4;
/// A draft left by a failed attempt is continued (not rewritten) when it has at least this
/// many words and a table of contents.
pub const CONTINUE_DRAFT_MIN_WORDS: usize = 1_500;
/// Words per rendered slide the enrichment loop aims for. The lint floor is a
/// shallow-output backstop (240); this is the quality target that stops the loop
/// early once a guide is genuinely deep enough.
pub const DEPTH_TARGET_WORDS_PER_SLIDE: usize = 450;

