#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
pub struct PhasePreset {
    pub provider: String,
    pub model: String,
    pub effort: String,
}

impl PhasePreset {
    fn new(provider: &str, model: &str, effort: &str) -> Self {
        Self {
            provider: provider.to_string(),
            model: model.to_string(),
            effort: effort.to_string(),
        }
    }
}

#[derive(Serialize, Clone, Debug, PartialEq, Eq)]
pub struct CourseProfile {
    pub id: String,
    pub label: String,
    pub root: String,
    pub guide_mode: String,
    pub description: String,
    pub require_slide_coverage: bool,
    pub require_visuals: bool,
    pub cumulative: bool,
}

impl CourseProfile {
    fn new(id: &str, label: &str, root: &str, guide_mode: &str, description: &str) -> Self {
        Self {
            id: id.to_string(),
            label: label.to_string(),
            root: root.to_string(),
            guide_mode: guide_mode.to_string(),
            description: description.to_string(),
            require_slide_coverage: true,
            require_visuals: true,
            cumulative: true,
        }
    }
}

