/// Check if a file path should be skipped based on folder names and filename patterns.
pub fn should_skip(filepath: &str) -> bool {
    let normalized = filepath.replace('\\', "/");
    let parts: Vec<&str> = normalized.split('/').collect();

    // Check skip folders (any path component)
    for part in &parts {
        let lower = part.to_lowercase();
        if [
            ".gwverify",
            ".gwwork",
            ".gwtxn",
            ".gwfailed",
            ".gwdelete",
            "_assets",
        ]
        .iter()
        .any(|suffix| lower.ends_with(suffix))
            || SKIP_FOLDERS.iter().any(|f| f.eq_ignore_ascii_case(part))
        {
            return true;
        }
    }

    // Check skip patterns (filename substring, case-insensitive)
    if let Some(filename) = parts.last() {
        let lower = filename.to_lowercase();
        if SKIP_PATTERNS.iter().any(|pattern| {
            if pattern.starts_with('.') {
                lower.ends_with(pattern)
            } else {
                lower.contains(pattern)
            }
        }) {
            return true;
        }
    }

    false // not skipped
}

/// Check if file extension is watched.
pub fn is_watched_extension(filepath: &str) -> bool {
    let lower = filepath.to_lowercase();
    WATCHED_EXTENSIONS.iter().any(|ext| lower.ends_with(ext))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn provider<'a>(config: &'a ConfigResponse, id: &str) -> &'a ProviderOption {
        config
            .providers
            .iter()
            .find(|provider| provider.id == id)
            .unwrap_or_else(|| panic!("missing provider {id}"))
    }

    #[test]
    fn cross_provider_pipeline_defaults_are_explicit_and_supported() {
        let config = ConfigResponse::new();
        let codex = provider(&config, "codex-chatgpt");

        assert_eq!(DEFAULT_PROVIDER, "codex-chatgpt");
        assert_eq!(DEFAULT_MODEL, "gpt-5.6-luna");
        assert_eq!(DEFAULT_EFFORT, "medium");
        assert_eq!(CODEX_PREP_PHASE_MODEL, "gpt-5.6-luna");
        assert_eq!(CODEX_PREP_PHASE_EFFORT, "medium");
        assert_eq!(codex.default_model, DEFAULT_MODEL);
        assert_eq!(codex.default_effort, DEFAULT_EFFORT);
        assert_eq!(codex.label, "OpenAI Codex (ChatGPT login)");

        assert_eq!(
            config.default_prep,
            PhasePreset::new("codex-chatgpt", "gpt-5.6-luna", "medium")
        );
        assert_eq!(
            config.collection_fallback_chain,
            [
                PhasePreset::new("codex-chatgpt", "gpt-5.6-terra", "medium"),
                PhasePreset::new("codex-chatgpt", "gpt-5.6-sol", "medium"),
            ]
        );
        assert_eq!(
            config.default_writer,
            PhasePreset::new("claude-code", "claude-opus-4-8", "high")
        );
        assert_eq!(
            config.fallback_chain,
            [PhasePreset::new("codex-chatgpt", "gpt-5.6-sol", "medium")]
        );
        let claude = provider(&config, "claude-code");
        assert_eq!(claude.label, "Claude Code (subscription login)");
        assert_eq!(
            claude.models,
            [
                "claude-opus-4-8",
                "claude-opus-5",
                "fable",
                "opus",
                "sonnet",
                "haiku"
            ]
        );
        assert_eq!(claude.default_model, "claude-opus-4-8");
        assert_eq!(claude.default_effort, "high");
    }

    #[test]
    fn codex_models_and_efforts_are_exposed_in_safe_order() {
        assert_eq!(
            CODEX_MODELS,
            ["gpt-5.6-sol", "gpt-5.6-terra", "gpt-5.6-luna"]
        );
        assert_eq!(CODEX_EFFORTS, ["low", "medium", "high", "xhigh", "max"]);
        assert!(!CODEX_EFFORTS.contains(&"ultra"));

        let config = ConfigResponse::new();
        let codex = provider(&config, "codex-chatgpt");
        assert_eq!(codex.models, CODEX_MODELS);
        assert_eq!(codex.efforts, CODEX_EFFORTS);
    }

    #[test]
    fn config_exposes_only_the_fixed_cli_provider_chain() {
        let config = ConfigResponse::new();
        let provider_ids = config
            .providers
            .iter()
            .map(|provider| provider.id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(provider_ids, ["codex-chatgpt", "claude-code"]);
        assert!(!config
            .providers
            .iter()
            .flat_map(|provider| provider.models.iter())
            .any(|model| model == "gpt-5.5"));

        let response = serde_json::to_value(config).expect("serialize config");
        for removed_field in [
            "default_base_url",
            "needs_api_key",
            "model_refresh",
            "default_prep_model",
            "default_prep_effort",
        ] {
            assert!(
                response["providers"]
                    .as_array()
                    .expect("provider array")
                    .iter()
                    .all(|provider| provider.get(removed_field).is_none()),
                "retired provider field leaked into config: {removed_field}"
            );
        }
    }

    #[test]
    fn fifth_semester_profiles_and_legacy_profile_are_exposed() {
        let config = ConfigResponse::new();
        let ids: Vec<&str> = config
            .course_profiles
            .iter()
            .map(|profile| profile.id.as_str())
            .collect();

        for expected in [
            "computer-networks",
            "computer-algorithms",
            "operating-systems",
            "circuit-lab",
            "scientific-writing",
            "legacy-fourth-semester",
        ] {
            assert!(ids.contains(&expected), "missing course profile {expected}");
        }
        assert!(config.course_profiles.iter().all(|profile| {
            profile.require_slide_coverage && profile.require_visuals && profile.cumulative
        }));
        assert_eq!(WATCH_DIR, FIFTH_SEMESTER_ROOT);
        assert!(WATCHED_EXTENSIONS.contains(&".pptx"));
        assert!(WATCHED_EXTENSIONS.contains(&".docx"));
    }

    #[test]
    fn should_skip_matches_folder_and_filename_boundaries_case_insensitively() {
        for path in [
            "course/node_modules/lecture.pdf",
            "course/NODE_MODULES/lecture.pdf",
            r"course\.git\lecture.pdf",
            "course/run.gwverify/slide.html",
            "course/RUN.GWVERIFY/slide.html",
            "course/run.gwwork/slide.html",
            "course/run.gwtxn/slide.html",
            "course/run.gwfailed/slide.html",
            "course/run.gwdelete/slide.html",
            "course/Guide_assets/slide.html",
            "course/syllabus-notes.pdf",
            "course/GUIDELINE.HTML",
            "course/unit.PREP.MD",
            "course/Introduction to NI ELVIS.pdf",
        ] {
            assert!(should_skip(path), "expected path to be skipped: {path}");
        }

        for path in [
            "",
            "course/node_modules_backup/lecture.pdf",
            "course/.gitignore/lecture.pdf",
            "course/run.gwverify.tmp/slide.html",
            "course/run.gwverify-backup/slide.html",
            "course/run.gwdelete.tmp/slide.html",
            "course/Guide_assets_backup/slide.html",
            "course/syllab.us-notes.pdf",
            "course/guide-line.html",
            "course/unit.prepmd.pdf",
            "course/unit.prep.md.pdf",
            "course/unit.prep.mdish.pdf",
        ] {
            assert!(
                !should_skip(path),
                "expected path to remain eligible: {path}"
            );
        }
    }

    #[test]
    fn watched_extensions_accept_case_variants_and_reject_malformed_near_matches() {
        for path in [
            "lecture.pdf",
            "lecture.PDF",
            "lesson.HtMl",
            "week-2.PPTX",
            "worksheet.DoCx",
            r"C:\course\deck.PdF",
        ] {
            assert!(
                is_watched_extension(path),
                "expected watched extension: {path}"
            );
        }

        for path in [
            "",
            "lecturepdf",
            "lecture.pdf.tmp",
            "lesson.htmlx",
            "deck.pptxm",
            "worksheet.docx.tmp",
            "lecture.pdf ",
            "course.pdf/notes.txt",
        ] {
            assert!(
                !is_watched_extension(path),
                "expected malformed or unsupported extension: {path}"
            );
        }
    }
}
